new:
const WORKLOAD_POLICY_VERSION: &str = "adr0135-workload-policy-v1";
const CATALOG_SCHEMA_VERSION: u32 = 1;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub(crate) enum BenchmarkRecordRoutingMode {
    SingleModel,
    Routed,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub(crate) enum BenchmarkRecordOutcome {
    Passed,
    Failed,
    Unavailable,
}

#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
pub(crate) struct BenchmarkExecutionIdentity {
    pub(crate) engine_commit_sha: TelemetryValue<String>,
    pub(crate) fixture_version: TelemetryValue<String>,
    pub(crate) fixture_fingerprint: TelemetryValue<String>,
    pub(crate) routing_mode: TelemetryValue<BenchmarkRecordRoutingMode>,
    pub(crate) experiment_id: TelemetryValue<String>,
    pub(crate) run_ordinal: TelemetryValue<u64>,
    pub(crate) repetition: TelemetryValue<u32>,
    pub(crate) run_started_unix_ms: TelemetryValue<u64>,
    pub(crate) run_finished_unix_ms: TelemetryValue<u64>,
    pub(crate) outcome: TelemetryValue<BenchmarkRecordOutcome>,
}

impl BenchmarkExecutionIdentity {
    fn comparison_identity_is_measured(&self) -> bool {
        matches!(&self.engine_commit_sha, TelemetryValue::Measured(value) if value.len() == 40 && value.chars().all(|character| character.is_ascii_hexdigit()))
            && matches!(&self.fixture_version, TelemetryValue::Measured(value) if !value.trim().is_empty())
            && matches!(&self.fixture_fingerprint, TelemetryValue::Measured(value) if !value.trim().is_empty())
            && matches!(self.routing_mode, TelemetryValue::Measured(_))
    }

    fn is_single_model_catalog_evidence(&self) -> bool {
        self.comparison_identity_is_measured()
            && self.routing_mode == TelemetryValue::Measured(BenchmarkRecordRoutingMode::SingleModel)
    }
}
